function isAllowedUser(fromId, allowedId) {
  if (fromId === undefined || fromId === null || allowedId === undefined || allowedId === null) {
    return false;
  }
  return String(fromId) === String(allowedId);
}

const payload = $input.first().json;
const message = payload.message ?? payload;
const fromId = message.from?.id;
if (!isAllowedUser(fromId, $env.TELEGRAM_ALLOWLIST_USER_ID)) {
  return [];
}
return [{ json: payload }];

const YOUTUBE_URL = /https?:\/\/(?:(?:www\.|m\.)?youtube\.com\/(?:watch\?(?:[^\s]*&)?v=|shorts\/|embed\/)|youtu\.be\/)([A-Za-z0-9_-]{11})[^\s]*/i;

function parseYoutubeMessage(text) {
  if (typeof text !== 'string' || text.length === 0) {
    return { ok: false };
  }
  const match = text.match(YOUTUBE_URL);
  if (!match) {
    return { ok: false };
  }
  const url = match[0].replace(/[),.;!?]+$/, '');
  const videoId = match[1];
  const notas = `${text.slice(0, match.index)} ${text.slice(match.index + match[0].length)}`.replace(/\s+/g, ' ').trim();
  return { ok: true, url, videoId, notas };
}

function replyText(kind, payload = {}) {
  switch (kind) {
    case 'not_youtube':
      return 'No pude guardar eso. Mándame un link de YouTube.';
    case 'duplicate':
      return 'Ese video ya está en la hoja.';
    case 'incomplete':
      return 'Lo guardé incompleto. Revisa la fila.';
    case 'sheets_failed':
      return 'No se guardó. Hubo un error con la hoja.';
    case 'saved': {
      const parts = [payload.marca, payload.modelo, payload.version, payload.anio].filter((part) => part !== undefined && part !== null && part !== '').join(' ');
      const nicho = payload.nicho ? ` · ${payload.nicho}` : '';
      return `Guardado: ${parts}${nicho}`;
    }
    default:
      return 'No se guardó. Hubo un error con la hoja.';
  }
}

const payload = $input.first().json;
const message = payload.message ?? payload;
const text = message.text ?? message.caption ?? '';
const parsed = parseYoutubeMessage(text);
const chatId = message.chat?.id;
if (!parsed.ok) {
  return [{ json: { ok: false, kind: 'not_youtube', chatId, reply: replyText('not_youtube') } }];
}
return [{ json: { ...parsed, kind: 'pending', chatId, reply: '' } }];

const parsed = $('Parse message').first().json;
const lookup = $input.first().json;
const found = Boolean(lookup.video_id);
function replyText(kind) {
  if (kind === 'duplicate') return 'Ese video ya está en la hoja.';
  return '';
}
if (found) {
  return [{ json: { ...parsed, kind: 'duplicate', reply: replyText('duplicate'), isDuplicate: true } }];
}
return [{ json: { ...parsed, isDuplicate: false } }];

const CARROCERIA = ['suv','sedan','coupe','hatchback','wagon','convertible','pickup','van','crossover'];
const NICHO = ['supercar','hypercar','grand_turismo','ultra_luxury','sports_sedan','muscle','suv_compacta','suv_mediana','suv_grande','off_road','pickup'];
const CONFIANZA = ['alta','media','baja'];

function pickEnum(value, list) {
  return typeof value === 'string' && list.includes(value) ? value : '';
}
function asTrimmedString(value) {
  return typeof value === 'string' ? value.trim() : '';
}
function asYear(value) {
  const n = typeof value === 'number' ? value : typeof value === 'string' ? Number(value) : NaN;
  if (!Number.isInteger(n) || n < 1900 || n > 2100) return '';
  return n;
}
function asPrice(value) {
  return typeof value === 'number' && Number.isFinite(value) ? value : '';
}
function sanitizeEnrichment(raw) {
  if (raw === null || raw === undefined || typeof raw !== 'object') {
    return { marca: '', modelo: '', version: '', anio: '', carroceria: '', nicho: '', precio_estimado: '', confianza: 'baja' };
  }
  return {
    marca: asTrimmedString(raw.marca),
    modelo: asTrimmedString(raw.modelo),
    version: asTrimmedString(raw.version),
    anio: asYear(raw.anio),
    carroceria: pickEnum(raw.carroceria, CARROCERIA),
    nicho: pickEnum(raw.nicho, NICHO),
    precio_estimado: asPrice(raw.precio_estimado),
    confianza: pickEnum(raw.confianza, CONFIANZA) || 'baja',
  };
}
function incompleteEnrichment() {
  return { marca: '', modelo: '', version: '', anio: '', carroceria: '', nicho: '', precio_estimado: '', confianza: 'baja' };
}
function buildSheetRow({ videoId, url, notas, enrichment, now }) {
  const e = enrichment ?? incompleteEnrichment();
  const fecha = now.toISOString().slice(0, 10);
  return [videoId, url, e.marca, e.modelo, e.version, e.anio, e.carroceria, e.nicho, e.precio_estimado, e.confianza, notas ?? '', fecha];
}
function replyText(kind, payload = {}) {
  switch (kind) {
    case 'incomplete':
      return 'Lo guardé incompleto. Revisa la fila.';
    case 'sheets_failed':
      return 'No se guardó. Hubo un error con la hoja.';
    case 'saved': {
      const parts = [payload.marca, payload.modelo, payload.version, payload.anio].filter((part) => part !== undefined && part !== null && part !== '').join(' ');
      const nicho = payload.nicho ? ` · ${payload.nicho}` : '';
      return `Guardado: ${parts}${nicho}`;
    }
    default:
      return 'No se guardó. Hubo un error con la hoja.';
  }
}

const parsed = $('Parse message').first().json;
const oembed = $('YouTube oEmbed').first().json;
const oembedOk = Boolean(oembed && oembed.title);
let raw;
try {
  const llm = $('LLM extract').first().json;
  const text = typeof llm.text === 'string' ? llm.text : (typeof llm.output === 'string' ? llm.output : null);
  if (text) {
    const cleaned = text.replace(/^```json\s*/i, '').replace(/```$/i, '').trim();
    raw = JSON.parse(cleaned);
  } else if (llm && typeof llm === 'object') {
    raw = llm;
  }
} catch (error) {
  raw = null;
}
const llmOk = raw !== null && typeof raw === 'object';
const enrichment = oembedOk && llmOk ? sanitizeEnrichment(raw) : incompleteEnrichment();
const kind = oembedOk && llmOk ? 'saved' : 'incomplete';
const row = buildSheetRow({
  videoId: parsed.videoId,
  url: parsed.url,
  notas: parsed.notas,
  enrichment,
  now: new Date(),
});
return [{
  json: {
    ...parsed,
    kind,
    enrichment,
    row,
    video_id: row[0],
    url: row[1],
    marca: row[2],
    modelo: row[3],
    version: row[4],
    anio: row[5],
    carroceria: row[6],
    nicho: row[7],
    precio_estimado: row[8],
    confianza: row[9],
    notas: row[10],
    fecha: row[11],
    reply: replyText(kind, enrichment),
  },
}];

function replyText(kind, payload = {}) {
  switch (kind) {
    case 'incomplete':
      return 'Lo guardé incompleto. Revisa la fila.';
    case 'sheets_failed':
      return 'No se guardó. Hubo un error con la hoja.';
    case 'saved': {
      const parts = [payload.marca, payload.modelo, payload.version, payload.anio].filter((part) => part !== undefined && part !== null && part !== '').join(' ');
      const nicho = payload.nicho ? ` · ${payload.nicho}` : '';
      return `Guardado: ${parts}${nicho}`;
    }
    default:
      return 'No se guardó. Hubo un error con la hoja.';
  }
}

const built = $('Build row').first().json;
const appendItem = $input.first();
const failed = Boolean(appendItem.error || appendItem.json?.error);
if (failed) {
  return [{ json: { ...built, kind: 'sheets_failed', reply: replyText('sheets_failed') } }];
}
return [{ json: { ...built, reply: replyText(built.kind, built.enrichment) } }];
